'use strict';
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cases=[
 {id:'race',week:6,code:'OS-601',title:'The missing update',module:'Threads & shared memory',brief:'Two booking workers each record one arrival. Both finish, but the shared counter sometimes increases only once. Reproduce the fault, then protect the whole update.',target:'Capture an unprotected lost update and a protected run ending at 2.',question:'What makes the protected result reliable in this model?',choices:['The CPU runs both threads simultaneously','The mutex makes the entire read–modify–write section mutually exclusive','Writing alone is protected; the read can remain outside'],answer:1,hint:'Both workers can read the same old value before either writes. Which operations must stay together?',deeper:'A mutex provides mutual exclusion, not automatic speed. A contending worker may block or spin depending on implementation. Atomic read–modify–write operations are another option for suitable data. This model treats lock acquisition as atomic and does not model memory-ordering rules.',prompt:'Use the trace to explain the lost update, identify the critical section, and discuss one cost or limitation of the remedy.',source:'threads-locks.pdf'},
 {id:'dead',week:6,code:'OS-602',title:'Both workers are waiting',module:'Locks & deadlock',brief:'A print worker and an audit worker each need the spool lock and the log lock. Their lock order differs. Neither finishes, although the CPU has spare capacity.',target:'Capture circular wait, then complete both workers using one global lock order.',question:'Which necessary deadlock condition does the shared ordering remove?',choices:['Mutual exclusion','No pre-emption','Circular wait'],answer:2,hint:'Compare who owns each lock with who is waiting for it. Adding another CPU does not release a lock.',deeper:'The four necessary conditions are mutual exclusion, hold-and-wait, no pre-emption of resources, and circular wait. CPU pre-emption is not the same as reclaiming an owned lock. Prevention changes the rules; detection and recovery deal with deadlock after it occurs. A consistent total order must be respected by every relevant code path.',prompt:'Name the four conditions, use this trace to locate the cycle, then explain a limitation of ordering or an alternative recovery policy.',source:'threads-bugs.pdf'},
 {id:'bottle',week:6,code:'OS-603',title:'More cores, same delay',module:'Resource efficiency',brief:'Twelve requests arrive together. Each needs 2 ms of CPU service followed by 6 ms on one serial storage device. Investigate whether adding a CPU core addresses the bottleneck.',target:'Run the baseline, test two CPU cores, then test faster storage with one core.',question:'What best explains the results for this workload?',choices:['The serial device limits completion; CPU utilisation alone is not the objective','Low CPU utilisation proves the OS is faulty','Doubling cores must halve elapsed time'],answer:0,hint:'Track completed requests and device utilisation. Keep the workload fixed when comparing configurations.',deeper:'This is a closed batch with unlimited queue capacity, no caching, no overhead and no contention outside the model. Throughput is completed requests divided by total elapsed time. A small CPU change need not improve a device-bound service. Real systems require measured workloads, latency distributions and repeated observations.',prompt:'Quote baseline and changed elapsed time and throughput. Explain why the preferred change works, and what real-system evidence you would need before recommending it.',source:'file-devices.pdf'},
 {id:'files',week:7,code:'OS-701',title:'The report cannot be opened',module:'Files & access control',brief:'A staff reader belongs to the readers group. The report is present, but opening /shared/report.txt fails. Restore the required access without exposing the file to a guest.',target:'Capture the denial; grant group search on the directory and group read on the file; keep guest access denied.',question:'Why is file read permission alone insufficient?',choices:['Every file must be executable to read it','The kernel also checks search permission on the directories in the path','A driver grants file permissions after reading the disk'],answer:1,hint:'Directory search (x) permits path traversal. Directory read (r) concerns listing names; it is not the same operation.',deeper:'This is a simplified POSIX-style access model, not NTFS. Owner is the administrator; the reader uses group permissions and the guest uses other permissions. / already allows search. ACLs, capabilities, links, mounts and mandatory controls are omitted. Metadata includes ownership, permissions, size and times; file contents are a separate concern.',prompt:'Explain the failed path lookup, justify the least-privilege change, and trace the successful cache-miss read from application to device and back.',source:'file-intro.pdf'},
 {id:'buffer',week:7,code:'OS-702',title:'Accepted is not persisted',module:'Devices & I/O queues',brief:'A logger produces 3 records per tick for 4 ticks. Storage writes 1 record per tick. A two-record volatile buffer loses data when full. Investigate a larger buffer, backpressure and a power cut.',target:'Capture overflow, complete a loss-free run, and run a power-cut experiment.',question:'What does a successful buffered write acceptance establish here?',choices:['The record is already on non-volatile storage','A larger buffer permanently increases device throughput','The record entered volatile memory; persistence still requires device completion'],answer:2,hint:'Each tick admits records before draining one. Watch accepted, persisted and lost counts separately.',deeper:'Buffering absorbs bursts; caching retains copies for reuse; spooling queues complete jobs for a device. Interrupts let a device signal completion; polling repeatedly checks its status. DMA can transfer blocks without CPU copying each byte, but still requires coordination. This model has no journalling, flush operation, device cache or power-loss protection.',prompt:'Compare capacity and backpressure as responses to the burst. Use the power-cut counts to explain durability and one limitation of this simplified device model.',source:'file-devices.pdf'},
 {id:'rtos',week:7,code:'OS-703',title:'The controller responds too late',module:'Constrained systems',brief:'An illustrative air-conditioning controller has 64 KiB RAM and one CPU. Control and telemetry jobs arrive every 5 ms. Control needs 1 ms and must finish within 2 ms of release; telemetry needs 3 ms.',target:'Capture missed control deadlines, exceed the memory budget once, then find a configuration that boots and meets all control deadlines.',question:'Which statement is supported by the successful run?',choices:['Any high-priority task always meets its deadline','This stated workload meets deadlines; blocking, interrupts and execution-time variation still need analysis','An RTOS is separate from all firmware'],answer:1,hint:'A response deadline concerns completion after release. Priority changes the order; queue capacity consumes memory.',deeper:'The model uses fixed-priority pre-emptive scheduling with zero switch cost and no blocking. It illustrates concepts relevant to a configured FreeRTOS system; it does not execute FreeRTOS. The firmware image may contain an RTOS, application logic and drivers. iOS could host a remote control app but is not this microcontroller OS. Priority inversion, watchdog design, safe actuator states and energy use need separate engineering.',prompt:'Compare deadlines and the RAM budget. Explain why the successful trace is not a general real-time guarantee and distinguish firmware, RTOS, driver and application responsibilities.',source:'https://www.freertos.org/Documentation/02-Kernel/02-Kernel-features/01-Tasks-and-co-routines/04-Task-scheduling'}
];
const KEY='riverside-os-lab-v1';
const routes=['home','week6','week7','check6','check7','report','library',...cases.map(c=>c.id)];
let progress={version:1,name:'',records:{},weeks:{},route:'home'},storageOK=true,current='home',sim={},feedback='',loadError='',rawRecovery='',restoring=false;
function cleanModel(id,m){
 if(!m||typeof m!=='object')return null;
 if(id==='race'||id==='dead')return {locked:m.locked===true,ordered:m.ordered===true,events:Array.isArray(m.events)?m.events.filter(x=>x===0||x===1).slice(0,100):[]};
 if(id==='bottle')return {cores:m.cores===2?2:1,disk:m.disk===2?2:6,ran:m.ran===true};
 if(id==='files')return {policy:['original','group','everyone'].includes(m.policy)?m.policy:'original',ran:m.ran===true};
 if(id==='buffer')return {capacity:m.capacity===9?9:2,policy:m.policy==='wait'?'wait':'drop',cut:m.cut===true,ran:m.ran===true};
 if(id==='rtos')return {priority:m.priority==='control'?'control':'telemetry',samples:[2,4,8].includes(m.samples)?m.samples:2,ran:m.ran===true};
 return null;
}
function validateImport(p){
 if(!p||p.version!==1||typeof p.name!=='string'||!p.records||typeof p.records!=='object'||Array.isArray(p.records))throw Error('This is not a Riverside OS Lab progress file.');
 const clean={version:1,name:p.name.slice(0,80),records:{},weeks:{},route:routes.includes(p.route)?p.route:'home'};
 for(const c of cases){const r=p.records[c.id];if(!r)continue;if(typeof r!=='object'||Array.isArray(r))throw Error('Invalid investigation record.');
  const d=clean.records[c.id]={note:typeof r.note==='string'?r.note.slice(0,12000):'',prediction:typeof r.prediction==='string'?r.prediction.slice(0,3000):'',choice:Number.isInteger(r.choice)&&r.choice>=0&&r.choice<3?r.choice:null,checks:{},snapshots:[],score:0,phase:['learn','experiment','explain'].includes(r.phase)?r.phase:'learn',review:Array.from({length:3},(_,i)=>r.review?.[i]===true),model:cleanModel(c.id,r.model)};
  for(const k of required(c.id))d.checks[k]=r.checks?.[k]===true;
  if(Array.isArray(r.snapshots))d.snapshots=r.snapshots.slice(-16).filter(x=>x&&typeof x.label==='string'&&typeof x.evidence==='string').map(x=>({label:x.label.slice(0,120),evidence:x.evidence.slice(0,18000)}));
  if(r.score===100&&eligible(c,d))d.score=100;
 }
 for(const w of [6,7]){const r=p.weeks?.[w]||{};clean.weeks[w]={answers:Course.weeks[w].quiz.map((q,i)=>Number.isInteger(r.answers?.[i])&&r.answers[i]>=0&&r.answers[i]<q.options.length?r.answers[i]:null),checked:r.checked===true,reflection:typeof r.reflection==='string'?r.reflection.slice(0,6000):'',reviewed:r.reviewed===true};}
 return clean;
}
try{rawRecovery=localStorage.getItem(KEY)||'';if(rawRecovery)progress=validateImport(JSON.parse(rawRecovery));}catch(e){loadError='Saved progress could not be read. Download a recovery copy or import a valid backup before starting again.';storageOK=false;}
function rec(id=current){return progress.records[id]||(progress.records[id]={note:'',prediction:'',choice:null,checks:{},snapshots:[],score:0,phase:'learn',review:[false,false,false],model:null});}
function weekRec(w){return progress.weeks[w]||(progress.weeks[w]={answers:Course.weeks[w].quiz.map(()=>null),checked:false,reflection:'',reviewed:false});}
function rememberModel(){if(!cases.some(c=>c.id===current)||restoring)return;rec().model=cleanModel(current,{...sim,ran:!!sim.result});}
function save(){
 if(!loadError){rememberModel();progress.route=current;try{localStorage.setItem(KEY,JSON.stringify(progress));storageOK=true;}catch{storageOK=false;}}
 const el=$('saveState');if(el)el.textContent=loadError?'Recovery needed · original data preserved':storageOK?'Saved in this browser · export before changing PCs':'Browser storage unavailable · export before closing';
}
function required(id){return Course.lessons[id].experiments.map(e=>e.check);}
function eligible(c,r){return required(c.id).every(k=>r.checks[k])&&r.choice===c.answer&&r.note.trim().length>=80&&r.review?.every(Boolean)&&r.review.length===3;}
function capture(flag,label,evidence){const r=rec();if(flag)r.checks[flag]=true;const old=r.snapshots.findIndex(x=>x.label===label);if(old>=0)r.snapshots.splice(old,1);r.snapshots.push({label,evidence});r.snapshots=r.snapshots.slice(-16);save();}
function init(id){if(id==='race')sim={...Models.race(false),events:[]};if(id==='dead')sim={...Models.deadlock(false),events:[]};if(id==='bottle')sim={cores:1,disk:6,result:null};if(id==='files')sim={policy:'original',result:null};if(id==='buffer')sim={capacity:2,policy:'drop',cut:false,result:null};if(id==='rtos')sim={priority:'telemetry',samples:2,result:null};}
function restoreModel(id){restoring=true;init(id);const m=rec(id).model;if(m){if(id==='race'||id==='dead'){sim=id==='race'?Models.race(m.locked):Models.deadlock(m.ordered);sim.events=[...m.events];for(const i of m.events)(id==='race'?Models.raceStep:Models.deadStep)(sim,i);}else{Object.assign(sim,m);if(m.ran)sim.result=id==='bottle'?Models.pipeline(sim.cores,sim.disk):id==='files'?Models.permissions(sim.policy):id==='buffer'?Models.buffer(sim.capacity,sim.policy,sim.cut):Models.controller(sim.priority,sim.samples);}}restoring=false;}
function nav(id){if(!routes.includes(id))return;save();current=id;if(location.hash!=='#'+id)history.pushState(null,'','#'+id);feedback='';if(cases.some(c=>c.id===id))restoreModel(id);render();document.body.classList.remove('menuopen');$('menu').setAttribute('aria-expanded','false');window.scrollTo(0,0);$('main').focus({preventScroll:true});}
function phase(name){rec().phase=name;feedback='';render();$('main').focus({preventScroll:true});window.scrollTo(0,0);}
function metrics(arr){return `<div class="metrics">${arr.map(([k,v])=>`<div class="metric"><span>${k}</span><strong>${v}</strong></div>`).join('')}</div>`;}
function trace(lines){return lines.length?`<ol class="trace" aria-label="Execution trace">${lines.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>`:'<p class="empty">Run the model to collect an execution trace.</p>';}
function select(id,label,values,value){return `<div><label for="${id}">${label}</label><select id="${id}">${values.map(([v,t])=>`<option value="${v}" ${String(v)===String(value)?'selected':''}>${t}</option>`).join('')}</select></div>`;}
function table(head,rows){return `<div class="tablewrap"><table><thead><tr>${head.map((h,i)=>`<th${i?' class="num"':''}>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map((c,i)=>`<td${i?' class="num"':''}>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function raceView(){return `<h2>Shared counter</h2><p class="small">Two workers · one increment each · sequentially consistent teaching model</p>${metrics([['Shared value',sim.value],['Expected at completion',2],['Mutex owner',sim.owner===null?'–':['A','B'][sim.owner]]])}<div class="controls">${select('lock','Protection',[[0,'No lock'],[1,'Mutex around full update']],sim.locked?1:0)}<button id="resetSim">Reset model</button><button id="run" class="primary">Run competing workers</button></div><div class="steps">${['A','B'].map((n,i)=>`<div class="thread"><strong>Worker ${n}</strong><p>Next: ${['READ shared','ADD locally','WRITE shared','Finished'][sim.pc[i]]}<br>Local value: ${sim.local[i]??'–'}</p><button data-thread="${i}" ${sim.pc[i]===3?'disabled':''}>Step worker ${n}</button></div>`).join('')}</div>${trace(sim.log)}`;}
function deadView(){return `<h2>Resource ownership</h2>${table(['Resource','Owner'],[['Spool lock',sim.owners[0]===null?'Free':['A','B'][sim.owners[0]]],['Log lock',sim.owners[1]===null?'Free':['A','B'][sim.owners[1]]]])}<div class="controls">${select('order','Acquisition order',[[0,'A: spool → log; B: log → spool'],[1,'Both: spool → log']],sim.ordered?1:0)}<button id="resetSim">Reset model</button><button id="run" class="primary">Run workers</button></div><div class="steps">${['A','B'].map((n,i)=>`<div class="thread"><strong>Worker ${n}</strong><p>${sim.pc[i]===3?'Completed':`Acquired ${sim.pc[i]} of 2 locks`}</p><button data-thread="${i}" ${sim.pc[i]===3?'disabled':''}>Step worker ${n}</button></div>`).join('')}</div><p class="notice">${Models.isDead(sim)?'Circular wait: A waits for B’s log lock; B waits for A’s spool lock.':sim.pc.every(x=>x===3)?'Both workers completed and released their resources.':'Inspect ownership, then advance either worker.'}</p>${trace(sim.log)}`;}
function bottleView(){const r=sim.result;return `<h2>Batch workload</h2><p>12 requests at t = 0. Each uses CPU for 2 ms, then the serial device. Device service starts on the next tick after CPU completion.</p><div class="controls">${select('cores','CPU cores',[[1,'1 core'],[2,'2 cores']],sim.cores)}${select('disk','Device service per request',[[6,'6 ms'],[2,'2 ms']],sim.disk)}<button id="run" class="primary">Run batch</button></div>${r?`${metrics([['Elapsed',r.elapsed+' ms'],['Throughput',r.throughput.toFixed(3)+' requests/ms'],['CPU utilisation',r.cpuUtil.toFixed(1)+'%'],['Device utilisation',r.diskUtil.toFixed(1)+'%']])}${table(['Request','Completion (ms)'],r.jobs.map(j=>['Request '+j.id,j.finish]))}<details><summary>Inspect per-millisecond execution</summary>${table(['Time (ms)','CPU job(s)','Device job','Queued for device'],r.timeline.map(x=>[x.start,x.cpu,x.disk,x.queue]))}</details>`:'<p class="empty">Run the baseline before changing the resources.</p>'}`;}
function filesView(){const r=sim.result;return `<h2>File access inspector</h2>${table(['Object','Owner','Group','Original permissions'],[['/shared','admin','readers','rwx------'],['report.txt','admin','readers','rw-------']])}<p class="small">Reader is not the owner; reader belongs to readers. Guest belongs to neither. This is an intentionally restricted POSIX-style model.</p><div class="controls">${select('policy','Access change',[['original','Keep original permissions'],['group','Group: directory x + file r'],['everyone','Everyone: directory x + file r']],sim.policy)}<button id="run" class="primary">Test reader and guest</button></div>${r?metrics([['Reader',r.allowed?'Allowed':'Denied'],['Guest',r.guestAllowed?'Allowed':'Denied']]):''}<div class="flow">${['Application','Kernel / access','File system','Driver','Device'].map(n=>`<span>${n}</span>`).join('')}</div>${trace(r?.log||[])}`;}
function bufferView(){const r=sim.result;return `<h2>Volatile write buffer</h2><p class="small">Ticks 1–4: 3 new records/tick. Admission precedes device drain: 1 record/tick. Power cut stops the model after tick 4.</p><div class="controls">${select('capacity','Buffer capacity',[[2,'2 records'],[9,'9 records']],sim.capacity)}${select('backpressure','When buffer is full',[['drop','Drop unaccepted records'],['wait','Backpressure: hold at producer']],sim.policy)}${select('cut','Power supply',[[0,'Continuous power'],[1,'Cut after tick 4 drain']],sim.cut?1:0)}<button id="run" class="primary">Run logger</button></div>${r?`${metrics([['Generated',r.generated],['Accepted',r.accepted],['Persisted',r.persisted],['Dropped / lost',`${r.dropped} / ${r.lost}`]])}${table(['Tick','New','Admitted','Buffer','Producer waiting','Persisted'],r.rows.map(x=>[x.t,x.arrived,x.accepted,x.queue,x.pending,x.persisted]))}<p class="notice">${r.cut?`${r.lost} accepted records were lost from volatile memory; ${r.pending} records remained at the producer. No automatic restart is modelled.`:`${r.persisted} records persisted; ${r.dropped} dropped; ${r.queue} buffered; ${r.pending} waiting at producer.`}</p>`:'<p class="empty">Run the small-buffer baseline to observe overflow.</p>'}`;}
function rtosView(){const r=sim.result;return `<h2>Air-conditioning controller</h2><p class="small">One CPU · 20 ms window · fixed-priority pre-emption · control 1 ms / period 5 ms / relative deadline 2 ms · telemetry 3 ms / period 5 ms</p><div class="controls">${select('priority','Higher-priority task',[['telemetry','Telemetry'],['control','Control']],sim.priority)}${select('samples','Queue allocation',[[2,'2 × 4 KiB blocks'],[4,'4 × 4 KiB blocks'],[8,'8 × 4 KiB blocks']],sim.samples)}<button id="run" class="primary">Boot and run 20 ms</button></div><p>RAM = 32 KiB platform + 2 × 8 KiB task stacks + queue allocation. Available: 64 KiB. Blocks are illustrative allocations, not a claim that a temperature reading occupies 4 KiB.</p>${r?`${metrics([['RAM required',r.memory+' KiB'],['Boot',r.boot?'Ready':'Rejected'],['Control misses',r.boot?r.misses:'–']])}<div class="bar" aria-label="RAM ${r.memory} of 64 KiB"><span style="width:${Math.min(100,r.memory/64*100)}%"></span></div>${r.boot?`<div class="tablewrap"><div class="timeline">${r.rows.map(x=>`<div class="tick ${x.task==='Control'?'control':''}" title="${x.t}–${x.t+1} ms: ${x.task}">${x.task[0]}<span>${x.t}</span></div>`).join('')}</div></div><p class="legend">C = Control · T = Telemetry · I = Idle. Each cell spans 1 ms; final cell ends at 20 ms.</p>${table(['Control release (ms)','Deadline (ms)','Finished (ms)','Result'],r.jobs.filter(j=>j.name==='Control').map(j=>[j.release,j.deadline,j.finish,j.finish<=j.deadline?'Met':'Missed']))}`:'<p class="notice">Requested allocation exceeds available RAM. No task executes; a deadline count would be meaningless.</p>'}`:'<p class="empty">Run the original telemetry-first configuration.</p>'}`;}
function checkLabels(id){return Object.fromEntries(Course.lessons[id].experiments.map(e=>[e.check,e.title+' captured']));}
function lessonSources(l){return `<p class="small">Sources: ${l.sources.map(([t,u])=>`<a href="${u}" target="_blank" rel="noopener">${t}</a>`).join(' · ')}. Linked reading is optional for the core route and requires internet access.</p>`;}
function notebook(r){return `<section class="panel"><h2>Evidence notebook</h2><p class="small">Snapshots update automatically when you run experiments. Reset model and Set up this run keep your written work and captured evidence.</p>${r.snapshots.length?r.snapshots.map((s,i)=>`<details id="evidence-${i}"><summary>${i+1}. ${esc(s.label)}</summary><pre class="reporttext">${esc(s.evidence)}</pre></details>`).join(''):'<p>No evidence yet. Start the first experiment and use its Run button.</p>'}</section>`;}
function investigation(c){const r=rec(),l=Course.lessons[c.id];return `<header class="case"><div><p class="eyebrow">Week ${c.week} / ${c.code} / approximately ${l.minutes} minutes</p><h1>${c.title}</h1><p class="brief">${l.aim}</p></div><button data-nav="week${c.week}">Week ${c.week} route</button></header><div class="stage-nav" aria-label="Investigation stages">${[['learn','1. Learn & predict'],['experiment','2. Experiment'],['explain','3. Explain & review']].map(([id,t])=>`<button data-phase="${id}" aria-current="${r.phase===id?'step':'false'}">${t}</button>`).join('')}</div>
 ${r.phase==='learn'?`<section class="panel reading"><h2>Before you run the model</h2><p>${c.brief}</p>${l.learn.map(([t,p])=>`<h3>${t}</h3><p>${p}</p>`).join('')}<dl>${l.terms.map(([t,d])=>`<dt>${t}</dt><dd>${d}</dd>`).join('')}</dl>${lessonSources(l)}</section><section class="panel"><h2>Make a prediction</h2><label for="prediction">${l.prediction}</label><textarea id="prediction" maxlength="3000" maxlength="3000" placeholder="My prediction is… because…">${esc(r.prediction)}</textarea><p class="small">This is saved, not graded. A mistaken prediction is useful when you explain why the evidence changed your mind.</p><button data-phase="experiment" class="primary">Continue to experiments</button></section>`:''}
 ${r.phase==='experiment'?`<p class="notice">Follow the numbered experiments. Set up this run chooses the settings; you still press Run and inspect the result. You can also change the controls yourself.</p><div class="grid"><section class="panel" id="modelPanel" tabindex="-1">${({race:raceView,dead:deadView,bottle:bottleView,files:filesView,buffer:bufferView,rtos:rtosView}[c.id])()}<div class="feedback" role="status">${esc(feedback)}</div></section><section class="panel"><h2>Your experiments</h2><ol class="experiment-list">${l.experiments.map((e,i)=>`<li><h3>${e.title}</h3><p class="check-state">${r.checks[e.check]?'✓ Evidence captured':'○ Not captured yet'}</p><p>${e.do}</p><p class="small"><strong>Look for:</strong> ${e.look}</p><button data-setup="${i}">Set up run ${i+1}</button></li>`).join('')}</ol><details id="hint"><summary>Stuck? Show a diagnostic hint</summary><p>${c.hint}</p><p>If your numbers differ from the worked debrief, use Set up run to restore that experiment, then Run. Manual worker steps can produce a different valid interleaving.</p></details><button data-phase="explain" class="primary">Continue to explanation</button></section></div>${notebook(r)}`:''}
 ${r.phase==='explain'?`<section class="panel reading"><h2>Compare and interpret</h2><p><strong>Your prediction:</strong> ${esc(r.prediction||'No prediction recorded.')}</p><details id="debrief"><summary>Reveal the worked debrief after comparing your runs</summary><p>${l.debrief}</p></details><details id="limits"><summary>Mechanism and model limits</summary><p>${c.deeper}</p></details><p><strong>Apply the idea:</strong> ${l.transfer}</p><ul>${l.selfcheck.map(x=>`<li>${x}</li>`).join('')}</ul>${lessonSources(l)}</section><section class="panel"><h2>Explain your evidence</h2><p>${c.prompt}</p><label for="reason">Your analysis (at least 80 characters)</label><textarea id="reason" maxlength="12000" maxlength="12000" placeholder="In the baseline… After changing… This happened because… A limitation is…">${esc(r.note)}</textarea><p class="small">Aim for one or two supported paragraphs. Length alone does not show understanding.</p><label for="diagnosis">${c.question}</label><select id="diagnosis" style="width:100%"><option value="">Select your conclusion</option>${c.choices.map((x,i)=>`<option value="${i}" ${r.choice===i?'selected':''}>${x}</option>`).join('')}</select><fieldset><legend>Review your own explanation</legend>${Course.review.map((t,i)=>`<label class="check-label"><input type="checkbox" data-review="${i}" ${r.review?.[i]?'checked':''}> ${t}</label>`).join('')}</fieldset><p class="small">Points record the experiments, conclusion and your self-review. The app cannot grade the quality of your prose. Ask your tutor about anything still unclear.</p><button id="submit" class="primary">Check investigation</button><div class="feedback" id="completionFeedback" role="status">${esc(feedback||(r.score?'100 practice points recorded. Your self-review is complete.':''))}</div></section>${notebook(r)}`:''}
 <div class="controls"><button data-nav="${cases.indexOf(c)===2?'check6':cases[cases.indexOf(c)+1]?.id||'check7'}">${cases.indexOf(c)===2?'Continue to Week 6 check':cases.indexOf(c)===5?'Continue to Week 7 check':'Next investigation'}</button><button id="startOver">Restart this investigation</button></div>`;}
function report(){return `<header class="case"><div><div class="eyebrow">Local evidence / Unit 50</div><h1>Session report</h1><p class="brief">${esc(progress.name||'Unnamed learner')} · ${total()} / 600 practice points. Scores are self-contained practice records, not authenticated assessment results.</p></div><button id="printReport">Print / save PDF</button></header><div class="controls"><button id="exportReport" class="primary">Download evidence report</button><button id="exportJSON">Export progress JSON</button></div>${cases.map(c=>{const r=rec(c.id);return `<section class="panel"><h2>${c.code} · ${c.title}</h2><p>${r.score||0} / 100 points · ${required(c.id).filter(k=>r.checks[k]).length} / ${required(c.id).length} practical checks</p><p><strong>Prediction:</strong> ${esc(r.prediction||'Not recorded.')}</p><p>Explanation self-review: ${r.review?.filter(Boolean).length||0}/3</p><p><strong>Analysis</strong></p><div class="reporttext">${esc(r.note||'No analysis recorded.')}</div><p><strong>Conclusion:</strong> ${esc(r.choice===null?'Not selected':c.choices[r.choice])}</p><details><summary>Captured evidence (${r.snapshots.length})</summary>${r.snapshots.map(s=>`<h3>${esc(s.label)}</h3><pre class="reporttext">${esc(s.evidence)}</pre>`).join('')}</details></section>`;}).join('')}`;}
function library(){return `<h1>Lab handbook</h1><p class="brief">Riverside OS Lab is an original teaching simulation for Unit 50, Level 5. It models selected mechanisms, not a complete operating system. All workloads, timings and device capacities are illustrative.</p><section class="panel"><h2>How to investigate</h2><ol><li>Predict what will happen before running the original configuration.</li><li>Reproduce the fault and inspect the trace.</li><li>Change one relevant variable and compare the outcome.</li><li>Explain the mechanism, trade-off and limits using the captured evidence.</li></ol><p>Each investigation awards 100 practice points once its experiments, conclusion, written response and self-review are complete. Editing the response requires a new self-review. Week checks and final reflections are recorded separately. Retrying never duplicates points. Text length only confirms that a response exists; it does not establish its quality.</p><p>Nothing you click changes a real OS, file permission or device. Later LO3 work must demonstrate real commands in the approved environments.</p></section><section class="panel"><h2>Sources and further reading</h2><ul class="resources"><li>Arpaci-Dusseau, R. H. and Arpaci-Dusseau, A. C. (2023). <em>Operating Systems: Three Easy Pieces</em>, version 1.10. <a href="https://pages.cs.wisc.edu/~remzi/OSTEP/" target="_blank" rel="noopener">Author-hosted textbook</a>. Chapters 26, 28, 30–32, 36 and 39 support the lecture principles.</li><li><a href="https://man7.org/linux/man-pages/man7/path_resolution.7.html" target="_blank" rel="noopener">Linux manual: path_resolution(7)</a> — search permissions and access failure.</li><li><a href="https://www.freertos.org/Documentation/02-Kernel/02-Kernel-features/01-Tasks-and-co-routines/04-Task-scheduling" target="_blank" rel="noopener">FreeRTOS task scheduling</a> — implementation context; our controller is not an emulator.</li></ul><p class="small">Sources consulted 5 November 2026. The simulations and their numerical datasets are original teaching examples.</p></section><section class="panel"><h2>Progress and access</h2><p>Your name or alias, notes and traces stay in this browser. There is no login, teacher dashboard or central leaderboard. Other people using this browser profile may see this work. Export progress before changing PCs. Import replaces the current local record after confirmation; it does not merge records.</p><p>Use buttons with a mouse or keyboard. All traces have text or table equivalents. On small screens, use Menu to switch investigations. The single-file download works offline; reference links require internet access.</p><p><a href="Riverside_OS_Lab_Offline.html" download>Download the offline lab</a> · <a href="resources.html">Week 6 and 7 teaching resources</a></p></section>`;}
function weekStats(w){const r=weekRec(w),data=Course.weeks[w],lessons=cases.filter(c=>c.week===w),done=lessons.filter(c=>rec(c.id).score===100).length,correct=r.checked?data.quiz.filter((q,i)=>r.answers[i]===q.answer).length:0;return {done,correct,complete:done===3&&r.checked&&correct===data.quiz.length&&r.reflection.trim().length>=120&&r.reviewed};}
function recoveryPanel(){return loadError?`<section class="panel"><h2>Recover your saved work</h2><p role="alert">${esc(loadError)}</p><div class="controls"><button id="recoveryDownload">Download unreadable record</button><button id="recoveryReset">Start fresh after backup</button></div><p>Use Import progress in the menu if you have a JSON backup. The original record will not be overwritten while this warning remains.</p></section>`:'';}
function home(){return `<header class="case"><div><p class="eyebrow">Unit 50 · Level 5 · Self-guided study</p><h1>Operating systems, one investigation at a time</h1><p class="brief">Two complete study routes. Read a short explanation, predict an outcome, investigate it, then defend your conclusion with evidence. No installation or specialist hardware is needed.</p></div></header>${recoveryPanel()}<section class="panel"><h2>Start here</h2><ol><li>Choose your week below. Work through its three investigations in order.</li><li>In each one, use Learn & predict → Experiment → Explain & review. Instructions and worked debriefs are included.</li><li>Finish the week’s knowledge check and reflection, then export your progress and evidence.</li></ol><p>Used an earlier version? Your saved notes and traces are retained. Complete the new experiment and self-review checks to confirm completion in these study routes.</p><p>Your theme changes appearance only. The same models run in DOS, XP, Windows 7 and Linux themes.</p><p class="small">All measurements are illustrative. This is formative practice, not an OS emulator or a replacement for real installation and command demonstrations.</p></section><div class="week-grid">${[6,7].map(w=>{const st=weekStats(w),d=Course.weeks[w];return `<section class="panel"><h2>Week ${w}: ${d.title}</h2><p>About 120 minutes, including a 5-minute screen break.</p><p>${st.done}/3 investigations complete · ${st.complete?'Week study route complete':'Week study route in progress'}</p><ul>${d.outcomes.map(t=>`<li>${t}</li>`).join('')}</ul><button data-nav="week${w}" class="primary">${st.done?'Continue':'Open'} Week ${w}</button></section>`;}).join('')}</div><section class="panel"><h2>Saving and getting help</h2><p>Work saves in this browser. Export progress creates a JSON backup to import on another PC. Session report produces a readable evidence file or PDF for submission through your normal course arrangements. Private browsing or cleared browser data may remove local work.</p><p>If stuck, use the diagnostic hint, restore the specified run settings and compare the worked debrief. Record any unresolved question in your explanation for your tutor. You can pause and return at any point.</p><button data-nav="report">Open session report</button></section>`;}
function weekView(w){const d=Course.weeks[w],st=weekStats(w);return `<header class="case"><div><p class="eyebrow">Self-guided route · approximately 120 minutes</p><h1>Week ${w}: ${d.title}</h1><p>${st.done}/3 investigations complete · ${st.complete?'Week route complete':'Work at your own pace; the timings are a guide.'}</p></div><button data-nav="home">All weeks</button></header>${recoveryPanel()}<section class="panel reading"><h2>Get ready</h2><p>${d.recap}</p>${d.recapSource?`<p class="small"><a href="${d.recapSource}" target="_blank" rel="noopener">Background: OSTEP threads</a></p>`:''}<h3>By the end of this week</h3><ul>${d.outcomes.map(x=>`<li>${x}</li>`).join('')}</ul><details id="week-plan"><summary>Suggested two-hour plan</summary>${table(['Activity','Minutes'],d.plan)}</details></section><section class="panel"><h2>Work through these investigations</h2><ol class="route-list">${cases.filter(c=>c.week===w).map(c=>`<li><h3>${c.code} · ${c.title}</h3><p>${Course.lessons[c.id].aim}</p><p class="small">${Course.lessons[c.id].minutes} minutes · ${rec(c.id).score===100?'Complete':rec(c.id).snapshots.length?'Started':'Ready to start'}</p><button data-nav="${c.id}">${rec(c.id).snapshots.length?'Resume':'Open'} ${c.code}</button></li>`).join('')}</ol><p class="notice">Take a five-minute screen break after the second investigation. Your notes and model state save automatically when browser storage is available.</p></section><section class="panel"><h2>Finish the week</h2><p>Apply the ideas to new questions, use the feedback to revisit misconceptions, then write a short synthesis and export your evidence.</p><button data-nav="check${w}" class="primary">Open Week ${w} knowledge check</button></section>`;}
function quizView(w){const d=Course.weeks[w],r=weekRec(w),st=weekStats(w);return `<header class="case"><div><p class="eyebrow">Week ${w} / consolidation</p><h1>Check your understanding</h1><p class="brief">These questions check concepts, not your writing. You can retry after using the explanations. Correct answers remain visible after checking so you can study them.</p></div><button data-nav="week${w}">Week ${w} route</button></header><section class="panel"><h2>Apply the ideas</h2>${d.quiz.map((q,i)=>`<fieldset class="quiz-question"><legend>${i+1}. ${q.q}</legend>${q.options.map((x,j)=>`<label class="check-label"><input type="radio" name="quiz-${i}" data-quiz="${i}" value="${j}" ${r.answers[i]===j?'checked':''}> ${x}</label>`).join('')}${r.checked?`<p class="notice"><strong>${r.answers[i]===null?'Not answered':r.answers[i]===q.answer?'Correct':'Revisit this idea'}.</strong> ${q.why} <strong>Supported answer:</strong> ${q.options[q.answer]}</p><button data-nav="${q.revisit}">Revisit ${cases.find(c=>c.id===q.revisit).code}</button>`:''}</fieldset>`).join('')}<button id="checkQuiz" class="primary">Check these answers</button><p role="status" id="quizStatus">${r.checked?`${st.correct}/${d.quiz.length} correct on this attempt. ${st.correct===d.quiz.length?'Continue to your reflection.':'Use the feedback, adjust your answers and check again.'}`:'Choose an answer for every question, then check.'}</p></section><section class="panel"><h2>Bring the week together</h2><label for="weekReflection">${d.exit}</label><textarea id="weekReflection" maxlength="6000" maxlength="6000">${esc(r.reflection)}</textarea><p class="small">Aim for one or two paragraphs, at least 120 characters. Use your own results. This response is saved but not automatically graded.</p><label class="check-label"><input id="weekReviewed" type="checkbox" ${r.reviewed?'checked':''}> I have checked that my reflection uses evidence and acknowledges a limitation.</label><p id="weekStatus" role="status">${weekStatus(w)}</p><div class="controls"><button id="checkWeek">Update week status</button><button data-nav="report" class="primary">Export my evidence</button>${w===6?'<button data-nav="week7">Continue to Week 7</button>':''}</div></section>`;}
function weekStatus(w){const st=weekStats(w),r=weekRec(w);return st.complete?'Week study route complete. Export your progress and evidence before leaving.':`Remaining: ${st.done<3?'complete the three investigations; ':''}${!r.checked||st.correct<5?'answer all five knowledge questions correctly; ':''}${r.reflection.trim().length<120?'write the final reflection (120+ characters); ':''}${!r.reviewed?'review the reflection; ':''}`.replace(/; $/,'.');}
function bindQuiz(w){const r=weekRec(w);document.querySelectorAll('[data-quiz]').forEach(b=>b.onchange=()=>{r.answers[Number(b.dataset.quiz)]=Number(b.value);r.checked=false;document.querySelectorAll('.quiz-question .notice,.quiz-question button').forEach(e=>e.remove());$('quizStatus').textContent='Answers changed. Check these answers again.';$('weekStatus').textContent=weekStatus(w);save();});$('checkQuiz').onclick=()=>{r.checked=true;render();$('quizStatus').scrollIntoView({block:'center'});};$('weekReflection').oninput=e=>{r.reflection=e.target.value;r.reviewed=false;$('weekReviewed').checked=false;$('weekStatus').textContent=weekStatus(w);save();};$('weekReviewed').onchange=e=>{r.reviewed=e.target.checked;$('weekStatus').textContent=weekStatus(w);save();};$('checkWeek').onclick=()=>{$('weekStatus').textContent=weekStatus(w);save();};}
function weekReports(){return [6,7].map(w=>{const r=weekRec(w),st=weekStats(w);return `<section class="panel"><h2>Week ${w} consolidation</h2><p>${st.complete?'Study route complete':'Study route not yet complete'} · ${r.checked?st.correct+'/5 correct on last checked attempt':'Knowledge answers not checked'}</p>${Course.weeks[w].quiz.map((q,i)=>`<p><strong>${q.q}</strong><br>${esc(r.answers[i]===null?'No answer':q.options[r.answers[i]])}</p>`).join('')}<h3>Final reflection</h3><p class="reporttext">${esc(r.reflection||'No reflection recorded.')}</p><p>Self-reviewed: ${r.reviewed?'Yes':'No'}. Written responses are not automatically graded.</p></section>`;}).join('');}
function weekText(){return [6,7].map(w=>{const r=weekRec(w),st=weekStats(w);return `WEEK ${w}: ${st.complete?'study route complete':'in progress'}\nKnowledge check: ${r.checked?st.correct+'/5':'not checked'}\n`+Course.weeks[w].quiz.map((q,i)=>`${q.q}\nAnswer: ${r.answers[i]===null?'Not answered':q.options[r.answers[i]]}`).join('\n\n')+`\nReflection: ${r.reflection||'Not recorded'}\nSelf-reviewed: ${r.reviewed?'Yes':'No'}`;}).join('\n\n');}

function total(){return cases.reduce((n,c)=>n+(progress.records[c.id]?.score===100?100:0),0);}
function render(){
 const active=document.activeElement,focusId=$('main').contains(active)?active.id:null,openDetails=[...$('main').querySelectorAll('details[open][id]')].map(d=>d.id);
 $('nav').innerHTML=`<button data-nav="home" aria-current="${current==='home'?'page':'false'}">Start / resume</button>`+[6,7].map(w=>`<div class="navgroup">Week ${w}</div><button data-nav="week${w}" aria-current="${current==='week'+w?'page':'false'}">Week ${w} study route</button>${cases.filter(c=>c.week===w).map(c=>`<button data-nav="${c.id}" aria-current="${current===c.id?'page':'false'}"><span class="navid">${c.code}${progress.records[c.id]?.score?' · complete':''}</span>${c.title}</button>`).join('')}<button data-nav="check${w}" aria-current="${current==='check'+w?'page':'false'}">Week ${w} knowledge check</button>`).join('')+`<div class="navgroup">Evidence & reference</div><button data-nav="report" aria-current="${current==='report'?'page':'false'}">Session report</button><button data-nav="library" aria-current="${current==='library'?'page':'false'}">Lab handbook</button>`;
 $('points').textContent=total()+' / 600 pts';$('learner').textContent=progress.name||'Learner workspace';
 $('main').innerHTML=current==='home'?home():current.startsWith('week')?weekView(Number(current.slice(4))):current.startsWith('check')?quizView(Number(current.slice(5))):current==='report'?report()+weekReports():current==='library'?library():investigation(cases.find(c=>c.id===current));
 document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>nav(b.dataset.nav));
 document.querySelectorAll('[data-phase]').forEach(b=>b.onclick=()=>phase(b.dataset.phase));
 if(current==='report'){ $('printReport').onclick=()=>window.print();$('exportReport').onclick=downloadReport;$('exportJSON').onclick=exportJSON; }
 else if(cases.some(c=>c.id===current))bind();
 else if(current.startsWith('check'))bindQuiz(Number(current.slice(5)));
 if($('recoveryDownload'))$('recoveryDownload').onclick=()=>download('Riverside_OS_Lab_Recovery.txt',rawRecovery,'text/plain');
 if($('recoveryReset'))$('recoveryReset').onclick=()=>{if(confirm('Start a fresh local record? Download the recovery copy first. This replaces unreadable progress in this browser.')){loadError='';rawRecovery='';save();render();}};
 openDetails.forEach(id=>{if($(id))$(id).open=true;});save();if(focusId&&$(focusId)&&!$(focusId).disabled)$(focusId).focus({preventScroll:true});
}
function refreshScore(){ $('points').textContent=total()+' / 600 pts';for(const c of cases){const el=document.querySelector('#nav [data-nav="'+c.id+'"] .navid');if(el)el.textContent=c.code+(rec(c.id).score===100?' · complete':'');}}
function bind(){
 const r=rec();
 if($('prediction'))$('prediction').oninput=e=>{r.prediction=e.target.value;save();};
 if($('reason'))$('reason').oninput=e=>{r.note=e.target.value;r.score=0;r.review=[false,false,false];document.querySelectorAll('[data-review]').forEach(b=>b.checked=false);refreshScore();$('completionFeedback').textContent='Explanation edited. Review it and check the investigation again.';save();};
 if($('diagnosis'))$('diagnosis').onchange=e=>{r.choice=e.target.value===''?null:Number(e.target.value);r.score=0;refreshScore();$('completionFeedback').textContent='Conclusion changed. Check the investigation again.';save();};
 document.querySelectorAll('[data-review]').forEach(b=>b.onchange=()=>{r.review[Number(b.dataset.review)]=b.checked;if(!b.checked)r.score=0;save();refreshScore();$('completionFeedback').textContent=r.score===100?'Investigation complete: 100 practice points.':'Review changed. Check the investigation again when ready.';});
 if($('submit'))$('submit').onclick=()=>{const c=cases.find(c=>c.id===current),missing=Course.lessons[current].experiments.filter(e=>!r.checks[e.check]);if(missing.length)feedback='Still needed: '+missing.map(e=>e.title).join('; ')+'. Return to 2. Experiment.';else if(r.choice!==c.answer)feedback=r.choice===null?'Select a conclusion, then check again.':'Revisit your conclusion: '+c.hint;else if(r.note.trim().length<80)feedback='Write at least 80 characters explaining the evidence, mechanism and a limitation.';else if(!r.review.every(Boolean))feedback='Review your explanation using all three checks before recording completion.';else{r.score=100;feedback='Investigation complete: 100 practice points. Compare your reasoning with the worked debrief, then continue.';}render();};
 $('startOver').onclick=()=>{if(confirm('Restart this investigation? Its notes, snapshots and points will be removed. Other investigations remain.')){delete progress.records[current];init(current);feedback='Investigation restarted.';render();}};
 document.querySelectorAll('[data-setup]').forEach(b=>b.onclick=()=>{const setup=Course.lessons[current].experiments[Number(b.dataset.setup)].setup;init(current);if(current==='race')sim={...Models.race(setup.locked),events:[]};else if(current==='dead')sim={...Models.deadlock(setup.ordered),events:[]};else Object.assign(sim,setup);feedback='Settings ready. Use the Run button, then inspect the result.';render();$('modelPanel').focus();$('modelPanel').scrollIntoView({block:'start'});});
 if($('resetSim'))$('resetSim').onclick=()=>{sim=current==='race'?{...Models.race(sim.locked),events:[]}:{...Models.deadlock(sim.ordered),events:[]};feedback='Model reset. Your evidence is retained.';render();};
 if(current==='race'&&$('lock')){$('lock').onchange=e=>{sim={...Models.race(e.target.value==='1'),events:[]};render();};document.querySelectorAll('[data-thread]').forEach(b=>b.onclick=()=>stepWorker(Number(b.dataset.thread)));}
 if(current==='dead'&&$('order')){$('order').onchange=e=>{sim={...Models.deadlock(e.target.value==='1'),events:[]};render();};document.querySelectorAll('[data-thread]').forEach(b=>b.onclick=()=>stepWorker(Number(b.dataset.thread)));}
 if($('run'))$('run').onclick=run;
 if(current==='bottle'&&$('cores')){ $('cores').onchange=e=>{sim.cores=Number(e.target.value);sim.result=null;render();};$('disk').onchange=e=>{sim.disk=Number(e.target.value);sim.result=null;render();}; }
 if(current==='files'&&$('policy'))$('policy').onchange=e=>{sim.policy=e.target.value;sim.result=null;render();};
 if(current==='buffer'&&$('capacity')){for(const [id,key] of [['capacity','capacity'],['backpressure','policy'],['cut','cut']])$(id).onchange=e=>{sim[key]=key==='capacity'?Number(e.target.value):key==='cut'?e.target.value==='1':e.target.value;sim.result=null;render();};}
 if(current==='rtos'&&$('priority')){ $('priority').onchange=e=>{sim.priority=e.target.value;sim.result=null;render();};$('samples').onchange=e=>{sim.samples=Number(e.target.value);sim.result=null;render();}; }
}
function stepWorker(i){if(sim.events.length>=100){feedback='Step limit reached. Reset the model to start a new trace; your evidence stays saved.';render();return;}sim.events.push(i);(current==='race'?Models.raceStep:Models.deadStep)(sim,i);(current==='race'?captureRace:captureDead)();render();const b=document.querySelector(`[data-thread="${i}"]`);if(b&&!b.disabled)b.focus({preventScroll:true});else $('run')?.focus({preventScroll:true});}
function captureRace(){if(sim.pc.every(x=>x===3)){if(!sim.locked&&sim.value===1)capture('baseline','Lost update: unprotected counter = 1',sim.log.join('\n'));if(sim.locked&&sim.value===2)capture('fixed','Protected counter = 2',sim.log.join('\n'));}}
function captureDead(){if(Models.isDead(sim))capture('baseline','Circular wait reproduced',sim.log.join('\n'));if(sim.ordered&&sim.pc.every(x=>x===3))capture('fixed','Global order: both completed',sim.log.join('\n'));}
function run(){
 feedback='';
 if(current==='race'){sim={...Models.race(sim.locked),events:[]};for(let n=0;n<8;n++){sim.events.push(0,1);Models.raceStep(sim,0);Models.raceStep(sim,1);}captureRace();}
 if(current==='dead'){sim={...Models.deadlock(sim.ordered),events:[]};for(let n=0;n<6;n++){sim.events.push(0,1);Models.deadStep(sim,0);Models.deadStep(sim,1);if(Models.isDead(sim)){sim.events.push(0,1);Models.deadStep(sim,0);Models.deadStep(sim,1);break;}}captureDead();}
 if(current==='bottle'){const r=sim.result=Models.pipeline(sim.cores,sim.disk),ev=`${r.cores} core(s); CPU service 2 ms; device service ${r.diskTime} ms\n12 jobs completed in ${r.elapsed} ms; throughput ${r.throughput.toFixed(3)} requests/ms\nCPU utilisation ${r.cpuUtil.toFixed(1)}%; device utilisation ${r.diskUtil.toFixed(1)}%\nCompletion times: ${r.jobs.map(j=>j.finish).join(', ')} ms`;
  const flag=sim.cores===1&&sim.disk===6?'baseline':sim.cores===2&&sim.disk===6?'extra':sim.cores===1&&sim.disk===2?'fixed':null;
  if(flag)capture(flag,`${sim.cores} core(s), ${sim.disk} ms device`,ev);else capture(null,'Two changes: 2 cores and faster device',ev); }
 if(current==='files'){const r=sim.result=Models.permissions(sim.policy);if(!r.allowed)capture('baseline','Original access denied',r.log.join('\n'));else if(!r.guestAllowed)capture('fixed','Reader allowed; guest denied',r.log.join('\n')+'\nGuest: denied');else {capture('unsafe','Reader and guest both allowed',r.log.join('\n')+'\nGuest: allowed');feedback='The reader can open the file, but so can a guest. Compare this with the group-only remedy.';}}
 if(current==='buffer'){const r=sim.result=Models.buffer(sim.capacity,sim.policy,sim.cut),ev=JSON.stringify(r,null,2);if(r.cut)capture('extra','Power cut after tick 4',ev);else if(r.dropped>0)capture('baseline','Buffer overflow',ev);else if(r.persisted===12)capture(r.policy==='wait'?'backpressure':'fixed',`All records persisted (${r.capacity} slots; ${r.policy})`,ev);}
 if(current==='rtos'){const r=sim.result=Models.controller(sim.priority,sim.samples),ev=JSON.stringify(r,null,2);if(!r.boot)capture('extra','RAM allocation rejected',ev);else if(r.misses>0)capture('baseline','Control deadlines missed',ev);else capture('fixed','All four control deadlines met',ev);}
 render();
}
function download(name,text,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;document.body.append(a);a.click();a.remove();$('message').textContent='Download requested: '+name+'. Check your browser downloads.';setTimeout(()=>URL.revokeObjectURL(url),5000);}
function exportJSON(){download('Riverside_OS_Lab_Progress.json',JSON.stringify(progress,null,2),'application/json');}
function downloadReport(){let lines=[`Riverside OS Lab — evidence report`,`Learner / alias: ${progress.name||'Not entered'}`,`Exported: ${new Date().toISOString()}`,`Practice points: ${total()}/600. Locally editable practice record; not authenticated assessment evidence.`,``];for(const c of cases){const r=rec(c.id);lines.push(`${c.code} ${c.title}`,`Points: ${r.score}/100`,`Prediction: ${r.prediction||'Not recorded'}`,`Self-review: ${r.review?.filter(Boolean).length||0}/3`,`Analysis: ${r.note||'Not recorded'}`,`Conclusion: ${r.choice===null?'Not selected':c.choices[r.choice]}`, ...r.snapshots.flatMap(s=>[s.label,s.evidence]),'');}lines.push(weekText());download('Riverside_OS_Lab_Evidence.txt',lines.join('\n\n'),'text/plain');}
document.getElementById('menu').onclick=()=>{document.body.classList.toggle('menuopen');$('menu').setAttribute('aria-expanded',document.body.classList.contains('menuopen'));};
$('export').onclick=exportJSON;$('import').onclick=()=>$('file').click();
$('file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2000000)throw Error('File is too large. Use an exported progress JSON file.');const p=validateImport(JSON.parse(await f.text()));if(confirm('Replace this browser’s current OS Lab progress with the imported record? Export your current work first if needed.')){progress=p;loadError='';rawRecovery='';current=p.route;history.replaceState(null,'','#'+current);if(cases.some(c=>c.id===current))restoreModel(current);render();$('message').textContent='Progress imported.';}}catch(err){$('message').textContent='Import failed: '+err.message;}e.target.value='';};
$('rename').onclick=()=>{const name=prompt('Name or alias for your evidence (stored only in this browser):',progress.name);if(name!==null){progress.name=name.slice(0,80);render();}};
current=routes.includes(location.hash.slice(1))?location.hash.slice(1):progress.route||'home';if(cases.some(c=>c.id===current))restoreModel(current);render();
window.addEventListener('hashchange',()=>{const id=location.hash.slice(1)||'home';if(routes.includes(id)&&id!==current)nav(id);});
let printDetails=[];
window.addEventListener('beforeprint',()=>{printDetails=[...document.querySelectorAll('details:not([open])')];printDetails.forEach(d=>d.open=true);});
window.addEventListener('afterprint',()=>{printDetails.forEach(d=>d.open=false);printDetails=[];});

// First-visit guidance is separate from learner evidence and can always be reopened.
const guideSteps=[
 ['Welcome to Riverside OS Lab','This is a simulated operating-system workspace. You will deliberately reproduce faults, change a setting, and explain what happens. Nothing you do here changes a real computer.','Start with the Week 6 study route, or select Week 7 if you have completed Week 6. Each route includes explanations, experiments, worked debriefs and a final knowledge check. Allow about two hours per week, including a break.'],
 ['Read, predict, run','Read the scenario and Investigation brief first. Predict what will happen, then use the Run button. The numbers and execution trace show what the model actually did.','For OS-601, leave Protection on No lock and select Run competing workers. Each worker adds one: does the final counter match your prediction? Step worker A and Step worker B let you inspect individual operations after resetting the model.'],
 ['Change one thing and explain','Change a setting and run again. Compare the result with your first run. The checklist records the required experiments; the Evidence notebook keeps snapshots automatically. Reset model keeps your evidence.','For OS-601, try Mutex around full update. In 3. Explain & review, write your explanation, choose a conclusion, complete the self-review checks and select Check investigation. Use the diagnostic hint if stuck. Points record practice completion; your tutor reviews the quality of your explanation.'],
 ['Save your work before leaving','Your work is saved in this browser only. Use Set name / alias to label it. Export progress downloads a JSON backup; Import progress restores that backup on another computer.','Use Session report to download evidence for your tutor or print to PDF. Export before changing computers or clearing browser data. Reopen these instructions at any time using Quick start or How to use this lab.']
];
const guide=document.createElement('dialog');guide.className='guide';guide.setAttribute('aria-labelledby','guideTitle');document.body.append(guide);
let guideStep=0,guideReturn=null;
function drawGuide(){const [title,body,detail]=guideSteps[guideStep];guide.innerHTML=`<p class="small">QUICK START / ${guideStep+1} OF ${guideSteps.length}</p><h2 id="guideTitle" tabindex="-1">${title}</h2><p>${body}</p><p class="notice">${detail}</p><div class="controls"><button id="guideBack" ${guideStep===0?'disabled':''}>Back</button><button id="guideNext" class="primary">${guideStep===guideSteps.length-1?'Start investigating':'Next'}</button><button id="guideClose">Close guide</button></div>`;$('guideBack').onclick=()=>{guideStep--;drawGuide();};$('guideNext').onclick=()=>{if(guideStep===guideSteps.length-1)guide.close();else{guideStep++;drawGuide();}};$('guideClose').onclick=()=>guide.close();$('guideTitle').focus();}
function openGuide(){guideReturn=document.activeElement;guideStep=0;drawGuide();guide.showModal();$('guideTitle').focus();}
guide.addEventListener('close',()=>{try{localStorage.setItem('riverside-os-guide-v1','seen');}catch{}if(guideReturn?.isConnected)guideReturn.focus();});
$('help').onclick=openGuide;$('helpTop').onclick=openGuide;
let guideSeen=false;try{guideSeen=localStorage.getItem('riverside-os-guide-v1')==='seen';}catch{}
if(!guideSeen)openGuide();

const desktopThemes=[['dos','MS-DOS','Text-mode blue, black and cyan.'],['xp','Windows XP','Luna-inspired blue title bars and warm grey windows.'],['seven','Windows 7','Aero-inspired pale blue frames and clean white workspaces.'],['linux','Linux / Ubuntu','Ubuntu-inspired aubergine panels and orange accents.']];
const themeDialog=document.createElement('dialog');themeDialog.className='guide theme-dialog';themeDialog.setAttribute('aria-labelledby','themeTitle');themeDialog.innerHTML='<h2 id="themeTitle">Choose your desktop</h2><p>Same investigations, different appearance. These are inspired themes, not emulations of the operating systems.</p><div class="theme-options">'+desktopThemes.map(([id,name,desc])=>`<button class="theme-choice" data-desktop="${id}" aria-pressed="false"><span class="theme-swatch swatch-${id}" aria-hidden="true"></span><strong>${name}</strong><span>${desc}</span></button>`).join('')+'</div><p class="small">Your choice is remembered in this browser. Your investigation and evidence stay as they are.</p><button id="closeTheme">Done</button>';document.body.append(themeDialog);
function setDesktop(id){if(!desktopThemes.some(t=>t[0]===id))id='dos';document.documentElement.dataset.theme=id;$('themeButton').textContent='Theme: '+desktopThemes.find(t=>t[0]===id)[1];themeDialog.querySelectorAll('[data-desktop]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.desktop===id));try{localStorage.setItem('riverside-os-theme',id);}catch{}}
let preferredDesktop='dos';try{preferredDesktop=localStorage.getItem('riverside-os-theme')||'dos';}catch{}setDesktop(preferredDesktop);
$('themeButton').onclick=()=>{themeDialog.showModal();themeDialog.querySelector('[aria-pressed="true"]').focus();};themeDialog.querySelectorAll('[data-desktop]').forEach(b=>b.onclick=()=>setDesktop(b.dataset.desktop));$('closeTheme').onclick=()=>themeDialog.close();themeDialog.addEventListener('close',()=>$('themeButton').focus());
